INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(1001, 'Genesis 35:8', 'Genesis', 35, 8, '&nbsp;د رِبقه خِدمتګاره دبوره مړه شوه او بيت‌ايل ته نزدې د څېړۍ د ونې لاندې ښخه شوه. نو ځکه د دې نوم ”د ژړا څېړۍ“ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1002, 'Genesis 35:9', 'Genesis', 35, 9, '&nbsp;چې کله يعقوب د مسوپتاميه نه راواپس شو، خُدائ پاک يعقوب ته بيا راڅرګند شو او هغۀ له يې برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1003, 'Genesis 35:10', 'Genesis', 35, 10, '&nbsp;خُدائ پاک هغۀ ته وفرمائيل، ”ستا نوم يعقوب دے، خو د نن نه پس ستا نوم اِسرائيل شو.“ نو د هغۀ نوم يې اِسرائيل کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1004, 'Genesis 35:11', 'Genesis', 35, 11, '&nbsp;او خُدائ پاک هغۀ ته وفرمائيل، ”زۀ قادر خُدائ يم. تۀ ډېر اولاد پېدا کړه. قومونه به ستا د اولاد نه جوړيږى او ستا په اولاد کښې به بادشاهان جوړيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1005, 'Genesis 35:12', 'Genesis', 35, 12, '&nbsp;زۀ به هغه مُلک تا له درکړم کوم چې ما اِبراهيم او اِسحاق له ورکړے وو او ستا نه پس به دا مُلک ستا اولاد له هم ورکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1006, 'Genesis 35:13', 'Genesis', 35, 13, '&nbsp;بيا خُدائ پاک د هغۀ نه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1007, 'Genesis 35:14', 'Genesis', 35, 14, '&nbsp;چرته چې خُدائ پاک د هغۀ سره خبرې کړې وې، نو يعقوب يو يادګارى کاڼے ودرولو او وقف يې کړو، مے او تېل يې پرې واچول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1008, 'Genesis 35:15', 'Genesis', 35, 15, '&nbsp;هغۀ په هغه ځائ بيت‌ايل نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1009, 'Genesis 35:16', 'Genesis', 35, 16, '&nbsp;بيا يعقوب او د هغۀ خاندان د بيت‌ايل نه کډه وکړه او چې کله دوئ د اِفرات نه لږ غوندې لرې وُو، د راحيل د ماشوم د پېدا کېدو وخت راغلو او هغه په سخت درد کښې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1010, 'Genesis 35:17', 'Genesis', 35, 17, '&nbsp;چې کله هغه د لنګون په دردونو کښې وه د هغې ماشوم پېدا شو، دايڼې هغې ته ووئيل، ”راحيل، يرېږه مه، اوس ستا بل زوئ هم شته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1011, 'Genesis 35:18', 'Genesis', 35, 18, '&nbsp;هغه مړه کېدله او د هغې ساه په وتلو وه، نو هغې په خپل زوئ بِن‌اَونى نوم کېښودو، خو يعقوب پرې بنيامين نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1012, 'Genesis 35:19', 'Genesis', 35, 19, '&nbsp;چې راحيل په حق ورسېده، نو هغه د اِفرات د لار په غاړه ښخه کړے شوه، چې هغه ځائ اوس د بيت‌لحم په نوم ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1013, 'Genesis 35:20', 'Genesis', 35, 20, '&nbsp;يعقوب هلته يو يادګارى کاڼے ودرولو او دا تر نن ورځې پورې د راحيل د قبر نښه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1014, 'Genesis 35:21', 'Genesis', 35, 21, '&nbsp;يعقوب بيا کډه يوړه او د عدر د څوکيدارۍ د برج بل طرف ته يې خېمه ولګوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1015, 'Genesis 35:22', 'Genesis', 35, 22, '&nbsp;چې کله يعقوب په هغه مُلک کښې اوسېدو، روبين لاړو او د خپل پلار د وينځې بِلهاه سره څملاستو، يعقوب د دې نه خبر شو او غصه شو. د يعقوب دولس زامن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1016, 'Genesis 35:23', 'Genesis', 35, 23, '&nbsp;دا د لِياه زامن دى، روبين د يعقوب مشر زوئ، شمعون، ليوى، يهوداه، يساکار او زبولون.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1017, 'Genesis 35:24', 'Genesis', 35, 24, '&nbsp;د راحيل زامن يوسف او بنيامين وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1018, 'Genesis 35:25', 'Genesis', 35, 25, '&nbsp;د راحيل د وينځې بِلهاه زامن، دان او نفتالى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1019, 'Genesis 35:26', 'Genesis', 35, 26, '&nbsp;د لِياه د وينځې زِلفه زامن جاد او آشر وُو. دا د يعقوب زامن دى چې په مسوپتاميه کښې پېدا شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1020, 'Genesis 35:27', 'Genesis', 35, 27, '&nbsp;يعقوب واپس خپل پلار اِسحاق ته، حبرون سره نزدې ممرې ته راغلو، دا هغه ځائ دے چرته چې اِبراهيم او اِسحاق اوسېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1021, 'Genesis 35:28', 'Genesis', 35, 28, '&nbsp;د اِسحاق ټول عُمر يو سل اتيا کاله وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1022, 'Genesis 35:29', 'Genesis', 35, 29, '&nbsp;او اِسحاق ساه ورکړه او ښۀ په پوخ عُمر کښې وفات شو او هغه خپلو زامنو عِيسو او يعقوب ښخ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1023, 'Genesis 36:1', 'Genesis', 36, 1, '&nbsp;دا د عِيسو اولاد دے، چې د ادوم په نوم هم يادېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1024, 'Genesis 36:2', 'Genesis', 36, 2, '&nbsp;عِيسو دا کنعانۍ جينکۍ وادۀ کړې، د حِتى ايلون لور عده، د صبعون حِوى د عنه د زوئ لور، اُهليبامه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1025, 'Genesis 36:3', 'Genesis', 36, 3, '&nbsp;او د اِسمٰعيل لور د نبايوت خور، باسمت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1026, 'Genesis 36:4', 'Genesis', 36, 4, '&nbsp;د عده نه اليفز پېدا شو، د باسمت نه رعواېل پېدا شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1027, 'Genesis 36:5', 'Genesis', 36, 5, '&nbsp;او اُهليبامه نه يعوس، يعلام او قورح پېدا شول، د عِيسو دا ټول زامن د کنعان په مُلک کښې پېدا شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1028, 'Genesis 36:6', 'Genesis', 36, 6, '&nbsp;بيا عِيسو د خپلو ښځو، خپلو زامنو، لوڼو او د خپل کور ټولو خلقو سره او خپلو ټولو څاروو او د هغه هر څۀ سره چې هغۀ په کنعان کښې ګټلى وُو، روان شو او د خپل ورور يعقوب نه بل مُلک ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1029, 'Genesis 36:7', 'Genesis', 36, 7, '&nbsp;هغه ځکه لاړو چې په کوم ځائ کښې هغه او يعقوب اوسېدل هلته يې ګزاره نۀ کېدله، د هغوئ څاروى ډېر زيات وُو او نور دوئ په يو ځائ اوسېدلے نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1030, 'Genesis 36:8', 'Genesis', 36, 8, '&nbsp;نو عِيسو د غرونو مُلک ادوم کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1031, 'Genesis 36:9', 'Genesis', 36, 9, '&nbsp;دا د ادوميانو د پلار نيکۀ، د عِيسو اولاد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1032, 'Genesis 36:14', 'Genesis', 36, 14, '&nbsp;د عنه لور د صبعون نمسۍ چې د عِيسو ښځه وه د هغې نوم اُهليبامه وو، د هغې د عِيسو نه دا درې زامن پېدا شول، يعوس، يعلام او قورح.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1033, 'Genesis 36:15', 'Genesis', 36, 15, '&nbsp;دا د عِيسو اولاد نه جوړې شوې قبيلې دى. د عِيسو مشر زوئ اليفز د دې قبيلو پلار نيکۀ وو، تيمان، اومر، صفو، قنز،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1034, 'Genesis 36:16', 'Genesis', 36, 16, '&nbsp;قورح، جعتام او عماليق. دا ټول د عِيسو د ښځې عده اولاد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1035, 'Genesis 36:17', 'Genesis', 36, 17, '&nbsp;د عِيسو زوئ رعواېل د دې قبيلو پلار نيکۀ وو، نحت، زارح، سمه او مِزه. دا ټول د عِيسو د ښځې باسمت اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1036, 'Genesis 36:18', 'Genesis', 36, 18, '&nbsp;دا قبيلې د عِيسو د ښځې اُهليبامه اولاد دے چې هغه د عنه لور وه، يعوس، يعلام او قورح.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1037, 'Genesis 36:19', 'Genesis', 36, 19, '&nbsp;دا ټولې قبيلې د عِيسو په اولاد کښې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1038, 'Genesis 36:22', 'Genesis', 36, 22, '&nbsp;لوطان د حورى او هيمام قومونو پلار نيکۀ وو. د لوطان د خور تمنع نوم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1039, 'Genesis 36:23', 'Genesis', 36, 23, '&nbsp;سوبل د علوان، مانحت، عيبال، سفو او د اونام قومونو پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1040, 'Genesis 36:24', 'Genesis', 36, 24, '&nbsp;د صبعون دوه زامن آيه او عنه وُو. دا هغه عنه دے چې کله هغۀ د خپل پلار خرۀ څرول نو په صحرا کښې يې ګرمې چينې وموندلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1041, 'Genesis 36:27', 'Genesis', 36, 27, '&nbsp;ايصر د بِلهان، زعوان او عقان قومونو پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1042, 'Genesis 36:28', 'Genesis', 36, 28, '&nbsp;ديسان د عُوض او اران قومونو پلار نيکۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1043, 'Genesis 37:1', 'Genesis', 37, 1, '&nbsp;يعقوب د کنعان په مُلک کښې اوسېدو، چرته چې د هغۀ پلار د مسافر په توګه اوسېدلے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1044, 'Genesis 37:2', 'Genesis', 37, 2, '&nbsp;او دا د يعقوب د خاندان قيصه ده. د اوولسو کالو ځوان زلمى، يوسف، د وروڼو سره ګډې او چېلۍ څرولې، چې هغوئ د هغۀ د پلار د نورو ښځو، زِلفه او بِلهاه زامن وُو. هغۀ خپل پلار د هغه غلطو کارونو نه خبر کړو کوم چې د هغۀ وروڼو کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1045, 'Genesis 37:3', 'Genesis', 37, 3, '&nbsp;يعقوب د يوسف سره د نورو ټولو زامنو نه زياته مينه کوله، ځکه چې هغه د هغۀ د سپين سر زوئ وو. يعقوب د هغۀ دپاره د اوږدو لستُوڼو والا يوه ښُکلې چُوغه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1046, 'Genesis 37:4', 'Genesis', 37, 4, '&nbsp;چې کله د هغۀ وروڼو دا وليدل چې د هغوئ پلار د يوسف سره د هغوئ نه زياته مينه کوى، نو په هغوئ باندې هغه دومره بد لګېدو چې هغوئ به د هغۀ سره په سمه خولۀ خبرې هم نۀ کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1047, 'Genesis 37:5', 'Genesis', 37, 5, '&nbsp;يو ځل يوسف خوب وليدو نو چې هغۀ خپل وروڼه د دې نه خبر کړل، نو د هغوئ کينه د يوسف سره نوره هم زياته شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1048, 'Genesis 37:6', 'Genesis', 37, 6, '&nbsp;هغۀ ووئيل، ”ما چې کوم خوب ليدلے دے هغه واورئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1049, 'Genesis 37:7', 'Genesis', 37, 7, '&nbsp;مونږ ټولو په پټى کښې د غنمو ګېډۍ تړلې، ناڅاپه زما ګېډۍ پاڅېدله او نېغه ودرېدله. ستاسو ګېډۍ زما د ګېډۍ نه ګېرچاپېره تاو شوې او هغې ته ټيټې شوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1050, 'Genesis 37:8', 'Genesis', 37, 8, '&nbsp;د هغۀ وروڼو ترې تپوس وکړو، ”ستا څۀ خيال دے تۀ به بادشاه جوړېږې او په مونږ به بادشاهى کوې څۀ؟“ نو د يوسف د خوبونو او چې هغۀ د وروڼو په حقله څۀ فرمائيلى وُو په دې وجه، د هغوئ ورسره کينه نوره هم زياته شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1051, 'Genesis 37:9', 'Genesis', 37, 9, '&nbsp;بيا يوسف يو بل خوب وليدو او خپلو وروڼو ته يې ووئيل، ”ما يو بل خوب ليدلے دے، چې په هغې کښې ما نمر او سپوږمۍ وليدل او يوولس ستورى هم چې ما ته ټيټېدل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1052, 'Genesis 37:10', 'Genesis', 37, 10, '&nbsp;هغۀ دا خوب خپل پلار ته هم ووئيلو او پلار هغه ورټلو، ”دا څنګه خوب دے چې تا ليدلے دے؟ ستا خيال دا دے چې ستا مور، ستا وروڼه او زۀ، مونږ به راځو او تا ته به په زمکه پرېوځُو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1053, 'Genesis 37:11', 'Genesis', 37, 11, '&nbsp;يوسف په وروڼو بد لګېدو، خو د هغۀ پلار د هغۀ دا ټولې خبرې په خپل زړۀ کښې يادې ساتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1054, 'Genesis 37:12', 'Genesis', 37, 12, '&nbsp;يوه ورځ چې کله د يوسف وروڼه د خپل پلار رَمې څرولو له شِکم ته تلى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1055, 'Genesis 37:13', 'Genesis', 37, 13, '&nbsp;يعقوب يوسف ته ووئيل، ”زۀ غواړم چې تۀ شِکم ته لاړ شې، چرته چې ستا وروڼه رمه څروى.“ يوسف ورته ووئيل، ”زۀ تيار يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1056, 'Genesis 37:14', 'Genesis', 37, 14, '&nbsp;د هغۀ پلار ووئيل، ”لاړ شه او وګوره کۀ رمه او ستا وروڼه په خېر وى، بيا واپس راشه او ما خبر کړه.“ نو د هغۀ پلار هغه د حبرون مېدان نه ولېږلو او يوسف شِکم ته ورسېدو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1057, 'Genesis 37:15', 'Genesis', 37, 15, '&nbsp;او هلته د څرن په ځائ کښې اخوا دېخوا ګرځېدو چې کله يو سړى هغه وليدو نو تپوس يې ترې وکړو، ”تۀ څۀ پسې ګرځې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1058, 'Genesis 37:16', 'Genesis', 37, 16, '&nbsp;هغۀ ورته ووئيل، ”زۀ خپلو وروڼو پسې ګرځم، ما ته ووايه چې هغوئ خپله رمه چرته څروى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1059, 'Genesis 37:17', 'Genesis', 37, 17, '&nbsp;هغه سړى ورته ووئيل، ”هغوئ خو تلى دى. د هغوئ نه ما واورېدل چې دوئ دوتين ته ځى.“ نو يوسف په خپلو وروڼو پسې لاړو او هغوئ يې په دوتين کښې وموندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1060, 'Genesis 37:18', 'Genesis', 37, 18, '&nbsp;هغوئ هغه د لرې نه وليدو او د هغۀ د رسېدو نه مخکښې يې د هغۀ خِلاف منصوبه جوړه کړه او د هغۀ د وژلو فېصله يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1061, 'Genesis 37:19', 'Genesis', 37, 19, '&nbsp;هغوئ يو بل ته ووئيل، ”ګورئ، د خوبونو اُستاذ راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1062, 'Genesis 37:20', 'Genesis', 37, 20, '&nbsp;نو اوس راځئ، چې وې وژنو او په يو اوچ کوهى کښې يې وغورزوو. مونږ به وايو چې هغه يو ځنګلى ځناور خوړلے دے. بيا به مونږ وګورو چې د هغۀ د خوبونو څۀ نتيجه راوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1063, 'Genesis 37:21', 'Genesis', 37, 21, '&nbsp;روبين د هغوئ خبرې واورېدې او د هغۀ د بچ کولو کوشش يې وکړو. هغۀ ووئيل، ”يوسف به نۀ مړ کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1064, 'Genesis 37:22', 'Genesis', 37, 22, '&nbsp;هغۀ ووئيل، ”هغه په دې صحرا کښې دې کوهى ته وغورزوئ، خو د هغۀ وينه مۀ تويَوئ.“ هغۀ دا خبره د دې دپاره وکړه، چې د دوئ نه يې بچ کړى او هغه واپس خپل پلار له ولېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1065, 'Genesis 37:23', 'Genesis', 37, 23, '&nbsp;کله چې يوسف خپلو وروڼو له راغلو، هغوئ د هغۀ نه د اوږدو لستُوڼو والا ښُکلې چُوغه وويستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1066, 'Genesis 37:24', 'Genesis', 37, 24, '&nbsp;بيا هغوئ هغه اوچت کړو او هغه اوچ کوهى ته يې وغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1067, 'Genesis 37:25', 'Genesis', 37, 25, '&nbsp;چې کله دوئ روټۍ ته ناست وُو، نو هغوئ د اِسمٰعيليانو يو کاروان وليدو چې هغوئ د جِلعاد نه مِصر ته په سفر روان وُو. د هغوئ په اوښانو خوشبودارې مصالحې او عطر بار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1068, 'Genesis 37:26', 'Genesis', 37, 26, '&nbsp;يهوداه خپلو وروڼو ته ووئيل، ”زمونږ د ورور وژل او د هغۀ مرګ پټول به مونږ له څۀ فائده راکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1069, 'Genesis 37:27', 'Genesis', 37, 27, '&nbsp;راځئ چې هغه په دې اِسمٰعيليانو خرڅ کړُو. مونږ به هغۀ ته څۀ ضرر نۀ رسوُو، آخر بيا هم، هغه زمونږ ورور دے او زمونږ خپله وينه ده.“ د هغۀ وروڼه په دې راضى شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1070, 'Genesis 37:28', 'Genesis', 37, 28, '&nbsp;او چې کله څۀ سوداګر هلته تېرېدل، د هغۀ وروڼو يوسف د کوهى نه بهر راوويستلو او هغه يې د سپينو زرو په شلو سيکو په اِسمٰعيليانو باندې خرڅ کړو، نو هغوئ مِصر ته بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1071, 'Genesis 37:29', 'Genesis', 37, 29, '&nbsp;چې کله روبين واپس کوهى ته راغلو او وې ليدل چې يوسف هلته نۀ وو، نو هغۀ د خفګان په وجه خپلې جامې وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
