(1073, 'Genesis 37:31', 'Genesis', 37, 31, '&nbsp;بيا هغوئ يو چېلے حلال کړو او د يوسف چُوغه يې په وينه کښې ډُوبه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
