(1075, 'Genesis 37:33', 'Genesis', 37, 33, '&nbsp;هغۀ دا وپېژندله او وې فرمائيل، ”آو، دا چُوغه هم زما د زوئ ده. څۀ ځنګلى ځناورو هغه خوړلے دے. زما زوئ يوسف به په رښتيا سره ټوټې ټوټې شوے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1076, 'Genesis 37:34', 'Genesis', 37, 34, '&nbsp;يعقوب د خفګان نه خپلې جامې وشلولې او د ټاټ جامې يې واغوستلې. د زوئ په غم کښې هغه ډېرې ورځې غمژن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1077, 'Genesis 37:35', 'Genesis', 37, 35, '&nbsp;ټول زامن او لوڼه تسلۍ ورکولو له ورله راغلل، خو په هغۀ دې تسلۍ اثر ونۀ کړو او وې فرمائيل، ”زۀ به د خپل زوئ په غم کښې تر مرګه پورې ژاړم.“ نو هغه د خپل زوئ يوسف په غم کښې غمژن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1078, 'Genesis 37:36', 'Genesis', 37, 36, '&nbsp;په دې دوران کښې، سوداګرو يوسف په مِصر کښې، د فِرعون په يو آفسر، فوطيفار باندې خرڅ کړو، چې هغه د محل د فوجيانو مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1079, 'Genesis 38:1', 'Genesis', 38, 1, '&nbsp;هم هغه وخت يهوداه خپل وروڼه پرېښودل، لاړو او د حيره نومې يو سړى سره اوسېدو، چې هغه د عدولام د ښار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
