(1081, 'Genesis 38:3', 'Genesis', 38, 3, '&nbsp;د هغې يو زوئ وشو، چې هغۀ پرې عير نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1082, 'Genesis 38:4', 'Genesis', 38, 4, '&nbsp;هغه بيا اُميدواره شوه او يو بل زوئ يې پېدا شو او هغې پرې اونان نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1083, 'Genesis 38:5', 'Genesis', 38, 5, '&nbsp;د هغې يو بل زوئ وشو او د هغۀ نوم يې سيله کېښودو. يهوداه په کزيب کښې وو چې کله دا ماشوم پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
