(1085, 'Genesis 38:7', 'Genesis', 38, 7, '&nbsp;د عير سلوک د مالِک خُدائ په نظر کښې ډېر خراب وو او هغه ترې نارضا شو، نو مالِک خُدائ هغه مړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1086, 'Genesis 38:8', 'Genesis', 38, 8, '&nbsp;بيا يهوداه د عير ورور اونان ته ووئيل، ”لاړ شه او د خپلې کونډې ورندارې سره څمله. د هغې د خاوند د ورور په توګه د هغې سره خپله ذمه وارى پوره کړه، نو داسې ستا د ورور به هم اولاد وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1087, 'Genesis 38:9', 'Genesis', 38, 9, '&nbsp;خو اونان ته پته ولګېده چې هغه بچى به د اونان خپل نۀ وى، نو چې کله به هغه د خپلې کونډې ورندارې سره څملاستو نو هغۀ به د نر اوبۀ په زمکه څڅولې، چې داسې به د هغۀ د ورور بچى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1088, 'Genesis 38:10', 'Genesis', 38, 10, '&nbsp;هغۀ چې څۀ کول مالِک خُدائ ترې نه په دې نارضا شو او مالِک خُدائ هغه هم ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1089, 'Genesis 38:11', 'Genesis', 38, 11, '&nbsp;بيا يهوداه خپلې اِنږور تامار ته ووئيل، ”د خپل پلار کور ته لاړه شه او تر هغې پورې کونډه پاتې شه چې زما زوئ سيله لوئ شوے نۀ وى.“ هغۀ دا ځکه ووئيل چې هغه يرېدو چې سيله به ووژلے شى، لکه چې د هغۀ خپل وروڼه هم وژلے شوى وُو. نو تامار لاړه او د خپل پلار په کور کښې اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1090, 'Genesis 38:12', 'Genesis', 38, 12, '&nbsp;څۀ وخت وروستو د يهوداه ښځه مړه شوه. چې کله په هغۀ د غم ورځې تېرې شوې، هغه او د هغۀ ملګرى د عدولام حيره، تمنت ته لاړل، چرته چې د هغۀ د ګډو وړۍ کلېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1091, 'Genesis 38:13', 'Genesis', 38, 13, '&nbsp;تامار ته چا ووئيل چې د هغې سخر ګډو کلولو له تمنت ته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1092, 'Genesis 38:14', 'Genesis', 38, 14, '&nbsp;نو هغې د کونډتوب جامې وويستلې چې هغې اغوستې وې او مخ يې په څادر پټ کړو او د تمنت په لاره د عينيم ښار سره نزدې ورته کښېناسته. ځکه چې هغې ته ښۀ پته وه چې د يهوداه وړوکے زوئ لوئ شوے وو او تر اوسه پورې يې ودېدو له نۀ وه ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1093, 'Genesis 38:15', 'Genesis', 38, 15, '&nbsp;چې کله يهوداه هغه وليده، نو خيال يې دا وو چې ګنې کنجره ده، ځکه چې هغې خپل مخ پټ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1094, 'Genesis 38:16', 'Genesis', 38, 16, '&nbsp;هغه د لار په غاړه هغې له ورَغلو او وې وئيل، ”زۀ تا سره څملاستل غواړم.“ هغۀ ته پته نۀ وه چې هغه يې اِنږور ده. هغې ووئيل، ”تۀ به ما له څۀ راکړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1095, 'Genesis 38:17', 'Genesis', 38, 17, '&nbsp;هغۀ جواب ورکړو، ”زۀ به تا له د خپلې رَمې نه يوه چېلۍ درولېږم.“ هغې ووئيل، ”ټيک ده، خو تۀ ما له په ضمانت کښې څۀ راکړه چې د ځان سره يې تر هغې پورې کېږدم چې تا چېلۍ نۀ وى رالېږلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1096, 'Genesis 38:18', 'Genesis', 38, 18, '&nbsp;هغۀ ترې تپوس وکړو، ”زۀ په ضمانت کښې څۀ درسره کېږدم؟“ هغې ورته ووئيل، ”ستا په غاړه کښې خپل مهر سره د مزى او ستا په لاس کښې دا امسا.“ هغۀ دا څيزونه هغې له ورکړل. بيا دوئ څملاستل او هغه اُميدواره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1097, 'Genesis 38:19', 'Genesis', 38, 19, '&nbsp;تامار کور ته لاړه، څادر يې لرې کړو او د کونډتوب جامې يې بيا واغوستلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1098, 'Genesis 38:20', 'Genesis', 38, 20, '&nbsp;وروستو يهوداه خپل ملګرے حيره عدلامى د چېلۍ سره ورولېږلو چې د ضمانت څيزونه د هغه ښځې نه واپس راوړى، خو حيره هغه ونۀ مونده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
